-- 202: Arabic draft of the Help Center (all 268 texts), written by Claude for review.
-- Saved as AI_TRANSLATED so readers see it and translators can review it in the Workbench
-- (category Help Center). A translation is only added where its key's English still matches
-- the text it was made from, and never replaces one a person has edited or verified.
-- Safe to run more than once.

BEGIN;

VALUES ('HELP_DOCS', 'Help Center', 'LIST')
ON CONFLICT (category_code) DO NOTHING;

CREATE TEMP TABLE _tr202 (key_code text, base_text text, ar_text text) ON COMMIT DROP;


-- Keys the app has not synced yet (a fresh database): add them with this English.
SELECT 'HELP_DOCS', key_code, base_text FROM _tr202
ON CONFLICT (key_code) DO NOTHING;

SELECT tk.key_id, 'ar', n.ar_text, 'AI_TRANSLATED', 'Anthropic Claude:claude-opus-5-5', now()
FROM _tr202 n
JOIN bayanat.translation_keys tk ON tk.key_code = n.key_code AND tk.base_text = n.base_text
ON CONFLICT (key_id, language_code) DO UPDATE
  SET translated_text = EXCLUDED.translated_text, status_code = 'AI_TRANSLATED',
      model_ref_text = EXCLUDED.model_ref_text, translated_at = now(), verified_at = NULL, verified_by_user_id = NULL
  WHERE bayanat.translations.status_code IN ('MISSING', 'STALE', 'AI_TRANSLATED')
     OR bayanat.translations.translated_text IS NULL;

COMMIT;
